'use client'

import DashboardLayourt from "@/app/dashboard/dashboardLoyourt";
import { useEffect, useState, useMemo } from "react";
import { toast } from "sonner";
import axiosInstance from "@/api/axios";
import apiRoutes from "@/api/routes";
import routes from "@/app/routes";
import { MessageSquarePlus, Truck } from 'lucide-react';
import { startOfMonth, endOfMonth, isWithinInterval, startOfDay, endOfDay } from "date-fns"

import { DataTable } from "./data-table"
import Link from "next/link";
import { useApp } from "@/app/AppContext"

export default function index() {
    const { user } = useApp()

    const [reload, setReload] = useState(0)

    const [bons, setBons] = useState([])
    const [totalAmount, setTotalAmount] = useState(0)

    console.log("User agent's :", user)
    const isPermittedTo = (value) => {
        return user?.role?.permissions?.some((pr) => pr.name === value)
    }

    // filtres de données par poériode
    const [date, setDate] = useState({
        from: startOfMonth(new Date()),
        to: endOfMonth(new Date()),
    })

    //Initialization des données
    useEffect(() => {
        // Charge tous les bons
        toast.promise(
            () => axiosInstance.get(apiRoutes.allCommande),
            {
                loading: 'Chargement des bons de commande ...',
                success: (res) => {
                    console.log("Les bons :", res.data)
                    setBons(res.data || [])
                    return 'Bons chargés!'
                },
                error: (err) => err?.message || 'Erreur de chargement',
            }
        )
    }, [reload])

    // Bons filtrés par période (recalculé automatiquement)
    const filteredBons = useMemo(() => {
        if (!date?.from) return bons

        const from = startOfDay(date.from)
        const to = date.to ? endOfDay(date.to) : endOfDay(date.from)

        let bs = bons.filter((bon) => {
            const createdAt = new Date(bon.createdAt)
            return isWithinInterval(createdAt, { start: from, end: to })
        })

        // calcule du montant total des bons
        setTotalAmount(bs.reduce((a, b) => {
            return a + b?.montant
        }, 0))

        return bs;
    }, [bons, date])

    useEffect(() => {
        console.log("totalAmount :", totalAmount)
    }, [totalAmount])

    return <>
        <DashboardLayourt title="Liste des bons de commandes" icon={<Truck />}>
            {/* listes des bons de commande */}
            <div className="container mx-auto py-10">
                <div className="row d-flex justify-content-center">
                    {isPermittedTo('commande.view') ?
                        <div className="col-md-10">
                            <div className="flex justify-content-center">
                                <Link className="btn btn-md border shadow-sm rounded p-1 d-flex w-50 justify-content-center align-items-center mb-2" href={routes.bonCommande.create}><MessageSquarePlus className="mx-1" /> Ajouter un bon de commande</Link>
                            </div>
                            <DataTable
                                data={filteredBons}
                                setReload={setReload}
                                date={date}
                                setDate={setDate}
                                totalAmount={totalAmount}
                            />
                        </div> :
                        <p className="text-center text-danger">Vous n'êtes pas autorisé.e à acceder à cette page.</p>
                    }
                </div>
            </div>
        </DashboardLayourt>
    </>
}